NT = lambda n: "a1000000-0000-4000-8000-%012x" % n         # notifications
ALICE, BOB, CARLA, DAN, EVE, FAY, GUS, HAL = [P(n) for n in range(1, 9)]
A_S, B_S, C_S, D_S, E_S, F_S, G_S, H_S = [SUB(n) for n in range(1, 9)]
